static void main (Args _args)
{
    MetLoadId               loadId;
    METOrderShipmentBundlingReportHeaderTmp     bundlingReportHeaderTmp;
    METSalesOrderShipmentLoadHeader             shipmentLoadHeader;

    if (_args.dataset() == tableNum(METSalesOrderShipmentLoadHeader))
    {
        shipmentLoadHeader = _args.record();
        loadId = shipmentLoadHeader.LoadId;
    }
    else
    {
        throw warning("Load Id is not valid");
    }

    while select shipmentLoadHeader
        where shipmentLoadHeader.LoadId == loadId
    {
        bundlingReportHeaderTmp.LoadID = shipmentLoadHeader.LoadId;
        bundlingReportHeaderTmp.ShipmentID = shipmentLoadHeader.ShipmentId;
        bundlingReportHeaderTmp.Route = shipmentLoadHeader.Route;
        bundlingReportHeaderTmp.RouteStopNum = shipmentLoadHeader.RouteStopNum;
        bundlingReportHeaderTmp.insert();
    }

    boolean     isFirstReport = true;
    while select bundlingReportHeaderTmp
        order by Route, RouteStopNum asc
    {
        SrsReportRunController c = new SrsReportRunController();
        c.parmReportName(ssrsReportStr(METSalesOrderShipmentBundlingReport, NewReport));
        c.parmExecutionMode(SysOperationExecutionMode::Synchronous);

        c.parmShowDialog(isFirstReport);
        c.parmLoadFromSysLastValue(false);
        METSalesOrderShipmentBundlingReportContract contract = c.parmReportContract().parmRdpContract();

        contract.parmLoadId(bundlingReportHeaderTmp.LoadID);
        contract.parmShipmentId(bundlingReportHeaderTmp.ShipmentID);
        contract.parmIsFirstReport(isFirstReport);
        c.startOperation();

        isFirstReport = false;

    }
}
